const ago=t=>{const m=t?.toMillis?t.toMillis():Date.now();const s=(Date.now()-m)/1e3;if(s<60)return'baru saja';if(s<3600)return Math.floor(s/60)+'m';if(s<86400)return Math.floor(s/3600)+'j';if(s<604800)return Math.floor(s/86400)+'h';return new Date(m).toLocaleDateString('id-ID')};
