const loadImg=f=>new Promise((res,rej)=>{const i=new Image();i.onload=()=>res(i);i.onerror=rej;i.src=URL.createObjectURL(f)});
async function shrinkSq(f,size,q=.78){const i=await loadImg(f),m=Math.min(i.width,i.height),k=Math.min(1,size/m),c=document.createElement('canvas');c.width=c.height=Math.round(m*k);c.getContext('2d').drawImage(i,(i.width-m)/2,(i.height-m)/2,m,m,0,0,c.width,c.height);return c.toDataURL('image/jpeg',q)}
async function shrink(f,max,q=.78){const i=await loadImg(f);const k=Math.min(1,max/Math.max(i.width,i.height));const c=document.createElement('canvas');c.width=Math.round(i.width*k);c.height=Math.round(i.height*k);c.getContext('2d').drawImage(i,0,0,c.width,c.height);return c.toDataURL('image/jpeg',q)}
async function cutout(f){ // hapus background polos (flood-fill dari tepi, warna mirip sudut)
const i=await loadImg(f),n=160,k=Math.min(n/i.width,n/i.height),c=document.createElement('canvas');c.width=Math.round(i.width*k);c.height=Math.round(i.height*k);
const x=c.getContext('2d',{willReadFrequently:true});x.drawImage(i,0,0,c.width,c.height);const W=c.width,H=c.height,im=x.getImageData(0,0,W,H),d=im.data;
const cs=[0,W-1,(H-1)*W,H*W-1].map(p=>p*4);const bg=[0,1,2].map(j=>cs.reduce((s,o)=>s+d[o+j],0)/4);
const near=o=>Math.hypot(d[o]-bg[0],d[o+1]-bg[1],d[o+2]-bg[2])<62;const seen=new Uint8Array(W*H),st=[];
for(let a=0;a<W;a++)st.push(a,(H-1)*W+a);for(let b=0;b<H;b++)st.push(b*W,b*W+W-1);
while(st.length){const p=st.pop();if(seen[p])continue;seen[p]=1;if(!near(p*4))continue;d[p*4+3]=0;const px=p%W;if(px>0)st.push(p-1);if(px<W-1)st.push(p+1);if(p>=W)st.push(p-W);if(p<W*(H-1))st.push(p+W)}
x.putImageData(im,0,0);return c.toDataURL('image/png')}
function embed(url){url=(url||'').trim();if(!url)return'';let m;
if(m=url.match(/(?:youtube\.com\/(?:watch\?(?:.*&)?v=|shorts\/|embed\/)|youtu\.be\/)([\w-]{11})/))return`<div class="emb"><iframe src="https://www.youtube.com/embed/${m[1]}" allow="encrypted-media; picture-in-picture" allowfullscreen loading="lazy"></iframe></div>`;
if(m=url.match(/open\.spotify\.com\/(?:intl-[a-z]+\/)?(track|album|playlist|episode|show)\/(\w+)/))return`<div class="emb sp"><iframe src="https://open.spotify.com/embed/${m[1]}/${m[2]}" allow="encrypted-media" loading="lazy" style="height:152px"></iframe></div>`;
if(/^https?:\/\/.+\.(mp4|webm|mov)(\?.*)?$/i.test(url))return`<video class="vid" src="${esc(url)}" controls playsinline preload="metadata"></video>`;
if(/^https?:\/\/.+\.(mp3|m4a|ogg|wav)(\?.*)?$/i.test(url))return`<audio src="${esc(url)}" controls preload="none"></audio>`;return''}

