async function followers(uid){if(S.fc[uid]!=null)return S.fc[uid];try{const c=await getCountFromServer(query(collection(db,'follows'),where('followee','==',uid)));return S.fc[uid]=c.data().count}catch{return 0}}
const isBlue=u=>u.verified||u.official||(S.fc[u.uid]>=10000);
const av=(u,c='')=>u.photoURL?`<img class="av ${c}" src="${esc(u.photoURL)}" alt="">`:`<div class="av ${c}">${esc((u.displayName||u.username||'?')[0].toUpperCase())}</div>`;
const badges=u=>(isBlue(u)?BLUE:'')+(u.emojiBadge?`<img class="emj" src="${esc(u.emojiBadge)}" alt="">`:'')+(u.badges||[]).map(b=>b=='artist'?'<span class="pill">'+ic('mic')+' Artis</span>':b=='playlist'?'<span class="pill b">'+ic('music')+' Playlist</span>':'').join('')+(u.type&&u.type!='personal'&&isBlue(u)?`<span class="pill b">${u.type=='group'?'Grup':'Agensi'}</span>`:'');
const nameOf=u=>`<span class="nm">${esc(u.displayName||u.username)}</span>${badges(u)}`;

