async function createProfile(u,{username,displayName,type,password}){FX.checkName(username,displayName);try{localStorage.setItem('rvn_welcome_'+u.uid,'1')}catch{}
const lower=(username||'').trim().toLowerCase();if(!/^[a-z0-9_.]{3,20}$/.test(lower))throw Error('Username 3–20 karakter: huruf kecil, angka, _ atau .');if(RESERVED.includes(lower))throw Error('Username ini dicadangkan');
if(!u.email)throw Error('Akun tidak punya email');if(password&&password.length<6)throw Error('Sandi minimal 6 karakter');
if((await getDoc(doc(db,'usernames',lower))).exists())throw Error('Username sudah dipakai');
if(password&&!u.providerData.some(p=>p.providerId==='password'))await linkWithCredential(u,EmailAuthProvider.credential(u.email,password));
let ok=false,last;for(let i=0;i<6&&!ok;i++){const no='88'+String(Math.floor(Math.random()*1e8)).padStart(8,'0');
const b=writeBatch(db);b.set(doc(db,'accounts',no),{uid:u.uid});b.set(doc(db,'usernames',lower),{uid:u.uid,email:u.email});
b.set(doc(db,'users',u.uid),{uid:u.uid,username:lower,usernameLower:lower,displayName:(displayName||lower).trim().slice(0,40),bio:'',photoURL:'',bannerURL:'',link:'',type,agencyStatus:type=='personal'?'':'pending',balance:0,accNo:no,verified:false,official:false,affiliate:false,perks:{},badges:[],emojiBadge:'',createdAt:serverTimestamp()});
try{await b.commit();ok=true}catch(e){last=e}}
if(!ok)throw last;
try{const o=await getDoc(doc(db,'usernames',OFFICIAL));if(o.exists()&&o.data().uid!==u.uid)await setDoc(doc(db,'follows',u.uid+'_'+o.data().uid),{follower:u.uid,followee:o.data().uid,createdAt:serverTimestamp()})}catch{}}

