function go(v,a){closeSheet();MU.stop();MU.io?.disconnect();MU.io=null;MU.manual={};closeStory();S.vu.forEach(f=>f());S.vu=[];S.cid=null;S.tok++;S.view=v;S.arg=a;if(S.live&&!(v=='live'&&a==S.uid))endLive();try{S.tau?.pause();S.tcur=null}catch{}document.body.classList.toggle('inlive',v=='live');document.body.classList.toggle('onhome',v=='home');document.body.classList.toggle('inreels',v=='reels');window.scrollTo(0,0);
$$('[data-nav]').forEach(b=>b.classList.toggle('on',b.dataset.nav==v||(v=='reels'&&b.dataset.nav=='reels')||(v=='settings'&&b.dataset.nav=='profile')||(v=='thread'&&false)||(v=='profile'&&b.dataset.nav=='profile'&&(!a||a==S.uid))));
const m=$('#main');m.innerHTML='';({home:viewHome,explore:viewExplore,reels:viewReels,shop:viewShop,profile:viewProfile,chats:viewChats,thread:viewThread,bank:viewBank,live:viewLive,inv:viewInv,music:viewMusic,notifs:viewNotifs,...FX.views}[v]||viewHome)(a);if(S.dir){m.classList.remove('sl','sr');void m.offsetWidth;m.classList.add(S.dir=='l'?'sl':'sr');S.dir=null}}
const back=(v,a)=>`<div class="row pad"><button class="ib" data-act="go" data-v="${v}" ${a?`data-a="${a}"`:''}>${I.back}</button><h3>`;
const SK=`<div class="card"><div class="ph"><div class="sk av"></div><div class="sp"><div class="sk" style="height:12px;width:40%;margin-bottom:8px"></div><div class="sk" style="height:10px;width:25%"></div></div></div><div class="sk" style="height:220px;border-radius:0"></div><div class="pad"><div class="sk" style="height:12px;width:70%"></div></div></div>`;

/* ---------- BERANDA ---------- */
function viewHome(){const m=$('#main');m.innerHTML=`<div id="stories" class="stories"></div><div class="seg"><button class="${S.tab=='fy'?'on':''}" data-act="tab" data-t="fy">Untuk Kamu</button><button class="${S.tab=='fl'?'on':''}" data-act="tab" data-t="fl">Mengikuti</button></div><div id="newb"></div><div id="feed">${SK+SK}</div>`;
S.vu.push(onSnapshot(query(collection(db,'stories'),where('createdAt','>',new Date(Date.now()-864e5))),q=>{S.stories=q.docs.map(d=>({id:d.id,...d.data()}));drawStories()},()=>{}));
S.vu.push(onSnapshot(query(collection(db,'posts'),orderBy('createdAt','desc'),limit(60)),s=>{S.raw=s.docs.map(d=>({id:d.id,...d.data()})).filter(p=>p.type!='reel');S.posts=S.raw;
if(!S.order)S.order=FX.rankFeed(S.raw).map(p=>p.id);else{const have=new Set(S.order),nw=S.raw.filter(p=>!have.has(p.id));nw.filter(p=>p.uid==S.uid).forEach(p=>S.order.unshift(p.id));const o=nw.filter(p=>p.uid!=S.uid).length,b=$('#newb');if(b)b.innerHTML=o?`<button class="newb" data-act="refresh">${I.refresh} ${o} postingan baru · ketuk untuk memuat</button>`:''}
drawFeed()},e=>$('#feed').innerHTML=`<div class="card pad c">${esc(errMsg(e))}</div>`))}
async function drawFeed(){const t=S.tok,by=Object.fromEntries((S.raw||[]).map(p=>[p.id,p]));let ps=(S.order||[]).map(id=>by[id]).filter(Boolean);
if(Date.now()-(S.pinT||0)>60000){S.pinHtml=await FX.pinnedCard();S.pinT=Date.now()}ps=ps.filter(p=>p.id!=S.pinPid||!S.pinHtml);if(S.tab=='fl')ps=ps.filter(p=>S.following.has(p.uid)||p.uid==S.uid);
await Promise.all(ps.flatMap(p=>[getUser(p.uid),p.repostOf?getOrig(p.repostOf):0]));if(t!==S.tok)return;
const f=$('#feed');if(!f)return;f.innerHTML=(S.tab=='fl'?'':S.pinHtml||'')+(ps.length?ps.map(card).join(''):`<div class="card pad c mut">Belum ada postingan. Ayo posting yang pertama!</div>`);hydrate(f);FX.watchSeen(f)}
async function refreshFeed(){S.pinT=0;if(S.view=='home'){try{const s=await getDocs(query(collection(db,'posts'),orderBy('createdAt','desc'),limit(60)));S.raw=s.docs.map(d=>({id:d.id,...d.data()})).filter(p=>p.type!='reel');S.posts=S.raw}catch{}
S.order=FX.rankFeed(S.raw||[]).map(p=>p.id);const nb=$('#newb');if(nb)nb.innerHTML='';await drawFeed();window.scrollTo({top:0,behavior:'smooth'});toast('Beranda disegarkan')}else if(S.view=='reels')FX.views.reels()}
async function getOrig(id){if(S.pc[id]!==undefined)return S.pc[id];const s=await getDoc(doc(db,'posts',id));S.pc[id]=s.exists()?{id,...s.data()}:null;if(S.pc[id])await getUser(S.pc[id].uid);return S.pc[id]}
function postBody(p,mini){const imgs=p.images||[];return`${p.text?`<div class="pt">${FX.safe(p.text)}</div>`:''}${imgs.length?`<div class="car">${imgs.map(s=>`<img src="${esc(s)}" loading="lazy" alt="">`).join('')}</div>${imgs.length>1?`<div class="dots">${imgs.map((_,i)=>`<i class="${i?'':'on'}"></i>`).join('')}</div>`:''}`:''}${embed(p.video)}`}
function card(p){const u=S.users[p.uid]||{};let inner=FX.wrapBody(p,postBody(p));
if(p.repostOf){const o=S.pc[p.repostOf],ou=o&&S.users[o.uid];inner=(p.text?`<div class="pt">${FX.safe(p.text)}</div>`:'')+`<div class="quote">${o?`<div class="ph" data-act="go" data-v="profile" data-a="${o.uid}">${av(ou,'')}<div>${nameOf(ou)}<div class="un">@${esc(ou.username)}</div></div></div>${postBody(o)}`:'<div class="pad mut">Postingan asli sudah dihapus</div>'}</div>`}
const lk=S.liked[p.id],own=p.uid==S.uid||S.isAdmin;
return`<article class="card" data-pid="${p.id}" data-music="${esc(p.music||'')}"><div class="ph"><span data-act="go" data-v="profile" data-a="${p.uid}">${av(u)}</span><div class="sp" data-act="go" data-v="profile" data-a="${p.uid}"><div>${nameOf(u)}</div><div class="un">@${esc(u.username)} · ${ago(p.createdAt)}${p.repostOf?' · '+ic('repost')+' posting ulang':''}</div>${mline(p)}</div>${S.isAdmin?`<button class="ib" data-act="pinpost" data-id="${p.id}" aria-label="Sematkan">${I.pin}</button>`:''}${own?`<button class="ib" data-act="delpost" data-id="${p.id}">${I.more}</button>`:`<button class="ib" data-act="report" data-t="post" data-id="${p.id}" data-u="${p.uid}" aria-label="Laporkan">${I.flag}</button>`}</div>${inner}
<div class="acts"><button class="lk ${lk?'on':''}" data-act="like" data-id="${p.id}">${I.heart}<span>${(p.likeCount||0)+(p.boost||0)}</span></button><button data-act="cmt" data-id="${p.id}">${I.comment}<span>${p.commentCount||0}</span></button><button data-act="repost" data-id="${p.id}">${I.repost}</button><button data-act="share" data-id="${p.id}">${I.send}</button>${p.uid==S.uid?`<button data-act="promo" data-id="${p.id}" aria-label="Suntik like">${I.rocket}</button>`:''}${p.uid!=S.uid?`<button data-act="gift" data-to="${p.uid}" aria-label="Hadiah">${I.gift}</button>`:''}<span class="sp"></span><button class="sv ${S.saved[p.id]?'on':''}" data-act="save" data-id="${p.id}">${I.save}</button></div></article>`}
function hydrate(root){musicObserve(root);$$('.car',root).forEach(c=>c.addEventListener('scroll',()=>{const i=Math.round(c.scrollLeft/c.clientWidth);$$('i',c.nextElementSibling).forEach((d,k)=>d.classList.toggle('on',k==i))},{passive:true}));
$$('[data-pid]',root).forEach(async el=>{const id=el.dataset.pid;if(S.liked[id]===undefined){try{S.liked[id]=(await getDoc(doc(db,'posts',id,'likes',S.uid))).exists()}catch{S.liked[id]=false}$('.lk',el)?.classList.toggle('on',S.liked[id])}})}

/* ---------- BUAT POSTINGAN ---------- */
function createSheet(kind='photo'){if(kind=='reel')return ACT.reelup();const perks=S.me.perks||{};const sh=sheet(`<h3>Buat postingan</h3><div class="seg" style="margin:10px 0"><button class="${kind=='photo'?'on':''}" data-act="ckind" data-k="photo">${ic('image')} Foto</button><button class="${kind=='tweet'?'on':''}" data-act="ckind" data-k="tweet">${ic('comment')} Tweet</button><button class="${kind=='reel'?'on':''}" data-act="ckind" data-k="reel"> RVNREELS</button></div>
${kind=='reel'&&!perks.reels?`<div class="card pad c" style="margin:0">RVNREELS khusus akun <b>Centang Biru</b>.<br><button class="btn sm" style="margin-top:10px" data-act="go" data-v="shop">Beli di Toko</button></div>`:`
<textarea id="c_tx" maxlength="500" placeholder="${kind=='photo'?'Tulis caption…':'Apa yang terjadi?'}"></textarea>
${kind=='photo'?`<label>Foto (bisa lebih dari satu → carousel, maks 6). Otomatis dipotong persegi 1:1 seperti Instagram</label><input id="c_im" type="file" accept="image/*" multiple><div id="c_pv" class="row" style="gap:6px;margin-top:8px;flex-wrap:wrap"></div>`:''}
${kind=='reel'?`<label>URL video (.mp4 langsung atau link YouTube)</label><input id="c_vd" placeholder="https://…/video.mp4">`:''}
<label>Musik latar (opsional): hanya link Spotify. Otomatis diputar 30 detik saat postingan terlihat</label><input id="c_mu" placeholder="https://open.spotify.com/track/..."><div id="c_ex"></div><label>Undang kolaborator (opsional)</label><input id="c_col" placeholder="@username, maks 3" autocapitalize="none"><div style="height:14px"></div><button class="btn block" data-act="post" data-k="${kind}">Posting</button>`}`);
FX.exclUI(sh);$('#c_im',sh)?.addEventListener('change',e=>{const fs=[...e.target.files].slice(0,6);$('#c_pv').innerHTML=fs.map(f=>`<img src="${URL.createObjectURL(f)}" style="width:56px;height:56px;border-radius:10px;object-fit:cover">`).join('')})}
async function doPost(kind,btn){const text=($('#c_tx')?.value||'').trim(),music=($('#c_mu')?.value||'').trim(),video=($('#c_vd')?.value||'').trim();let images=[];
if(music&&!mkind(music))return toast('Musik hanya menerima link Spotify (track, album, atau playlist)');
if(text&&!FX.guard(text,'post'))return;if(kind=='reel'&&!embed(video))return toast('URL video harus .mp4 langsung atau link YouTube');
btn.disabled=true;try{if(kind=='photo'){const fs=[...($('#c_im').files||[])].slice(0,6);if(!fs.length)throw Error('Pilih minimal 1 foto');
let mx=1000,q=.75;for(let n=0;n<4;n++){images=await Promise.all(fs.map(f=>shrinkSq(f,mx,q)));if(images.join('').length<880000)break;mx=Math.round(mx*.75);q=Math.max(.5,q-.08)}
if(images.join('').length>=880000)throw Error('Foto terlalu besar, kurangi jumlahnya')}
if(kind=='tweet'&&!text)throw Error('Tulis sesuatu dulu');
const cu=[];for(const n of ($('#c_col')?.value||'').split(',').map(x=>x.trim().toLowerCase().replace('@','')).filter(Boolean).slice(0,3)){const us=await getDoc(doc(db,'usernames',n));if(!us.exists())throw Error('Username kolaborator tidak ditemukan: @'+n);if(us.data().uid!=S.uid&&!cu.includes(us.data().uid))cu.push(us.data().uid)}
const pref=doc(collection(db,'posts'));await setDoc(pref,{uid:S.uid,type:kind,text,images,music,video:kind=='reel'?video:'',...(cu.length?{collabInv:cu,collab:[]}:{}),...($('#c_exv')?.checked?{excl:true}:{}),repostOf:'',likeCount:0,commentCount:0,createdAt:serverTimestamp()});
cu.forEach(u=>pushNotif(u,'collab','mengundangmu berkolaborasi di postingannya','collab_'+pref.id,{pid:pref.id}));closeSheet();toast('Terposting');if(S.view!='home'&&kind!='reel')go('home')}catch(e){toast(errMsg(e));btn.disabled=false}}

/* ---------- LIKE / KOMENTAR / REPOST ---------- */
async function toggleLike(el){const id=el.dataset.id,was=!!S.liked[id],sp=$('span',el),n=+sp.textContent;S.liked[id]=!was;el.classList.toggle('on',!was);sp.textContent=Math.max(0,n+(was?-1:1));
try{const b=writeBatch(db),r=doc(db,'posts',id,'likes',S.uid);was?b.delete(r):b.set(r,{at:serverTimestamp()});b.update(doc(db,'posts',id),{likeCount:increment(was?-1:1)});await b.commit();if(!was){const p=S.posts?.find(x=>x.id==id)||S.pc[id];p&&pushNotif(p.uid,'like','menyukai '+kw(p)+' anda','like_'+id+'_'+S.uid,{pid:id})}}catch(e){S.liked[id]=was;el.classList.toggle('on',was);sp.textContent=n;toast(errMsg(e))}}
async function openComments(id){const sh=sheet(`<h3>Komentar</h3><div id="cl" style="min-height:120px;margin:10px 0"><div class="sk" style="height:40px"></div></div><div class="row"><input id="cm_in" placeholder="Tambah komentar…" maxlength="500"><button class="btn sm" data-act="sendcmt" data-id="${id}">Kirim</button></div>`);
S.su=onSnapshot(query(collection(db,'posts',id,'comments'),orderBy('createdAt','asc'),limit(100)),async s=>{const cs=s.docs.map(d=>({id:d.id,...d.data()}));await Promise.all(cs.map(c=>getUser(c.uid)));const l=$('#cl');if(!l)return;
l.innerHTML=cs.length?cs.map(c=>{const u=S.users[c.uid];return`<div class="row" style="align-items:flex-start;margin-bottom:12px">${av(u)}<div class="sp"><div>${nameOf(u)} <span class="un">${ago(c.createdAt)}</span></div><div>${fmt(c.text)}</div></div>${c.uid==S.uid||S.isAdmin?`<button class="mut" data-act="delcmt" data-p="${id}" data-id="${c.id}">${ic('x')}</button>`:''}</div>`}).join(''):'<p class="mut c">Belum ada komentar</p>'})}
async function sendComment(id){const i=$('#cm_in'),t=i.value.trim();if(!t)return;i.value='';try{const b=writeBatch(db);b.set(doc(collection(db,'posts',id,'comments')),{uid:S.uid,text:t,createdAt:serverTimestamp()});b.update(doc(db,'posts',id),{commentCount:increment(1)});await b.commit();const p=S.posts?.find(x=>x.id==id)||S.pc[id];p&&pushNotif(p.uid,'comment','mengomentari '+kw(p)+' anda: '+t.slice(0,60),undefined,{pid:id})}catch(e){toast(errMsg(e))}}
async function repost(id){const t=prompt('Tambah komentar untuk posting ulang (boleh kosong):');if(t===null)return;try{const o=S.pc[id]||S.posts?.find(p=>p.id==id);await setDoc(doc(collection(db,'posts')),{uid:S.uid,type:'tweet',text:t.trim().slice(0,500),images:[],music:'',video:'',repostOf:o?.repostOf||id,likeCount:0,commentCount:0,createdAt:serverTimestamp()});o&&pushNotif(o.uid,'repost','memposting ulang '+kw(o)+' anda',undefined,{pid:id});toast('Diposting ulang')}catch(e){toast(errMsg(e))}}
async function sharePost(id){const url=location.origin+location.pathname+'#post='+id;try{if(navigator.share)await navigator.share({title:'RVN NOISE',text:'Lihat postingan ini di RVNOISE',url});else{await navigator.clipboard.writeText(url);toast('Link disalin')}}catch{}}
async function toggleSave(el){const id=el.dataset.id,was=!!S.saved[id],r=doc(db,'users',S.uid,'saved',id);S.saved[id]=!was;el.classList.toggle('on',!was);try{was?await deleteDoc(r):await setDoc(r,{at:serverTimestamp()})}catch(e){toast(errMsg(e))}}

