function viewExplore(){const m=$('#main'),t=S.tok;m.innerHTML=`<div class="pad"><input id="q" placeholder="Cari username…" autocapitalize="none"></div><div class="seg"><button class="on" data-act="go" data-v="explore">Jelajah</button><button data-act="go" data-v="reels">${ic('film')} RVNREELS</button><button data-act="livepage">${ic('live')} Live</button></div><div id="res"></div><div id="grid" class="grid3">${'<div class="sk" style="aspect-ratio:1"></div>'.repeat(9)}</div>`;
let to;$('#q').addEventListener('input',e=>{clearTimeout(to);to=setTimeout(()=>search(e.target.value.trim().toLowerCase()),300)});
getDocs(query(collection(db,'posts'),orderBy('createdAt','desc'),limit(60))).then(async s=>{if(t!==S.tok)return;const ps=s.docs.map(d=>({id:d.id,...d.data()})).filter(p=>p.images?.length);$('#grid').innerHTML=ps.length?ps.map(p=>`<img src="${esc(p.images[0])}" data-act="go" data-v="profile" data-a="${p.uid}" loading="lazy">`).join(''):'<p class="mut c" style="grid-column:1/-1">Belum ada foto</p>'}).catch(()=>{})}
async function search(q){const r=$('#res');if(!r)return;if(!q){r.innerHTML='';return}
const s=await getDocs(query(collection(db,'users'),orderBy('usernameLower'),where('usernameLower','>=',q),where('usernameLower','<=',q+'\uf8ff'),limit(15)));
const us=s.docs.map(d=>({...d.data(),uid:d.id}));us.forEach(u=>S.users[u.uid]=u);await Promise.all(us.map(u=>followers(u.uid)));
r.innerHTML=us.length?`<div class="card">${us.map(u=>`<div class="chat-item" data-act="go" data-v="profile" data-a="${u.uid}">${av(u)}<div><div>${nameOf(u)}</div><div class="un">@${esc(u.username)}</div></div></div>`).join('')}</div>`:'<p class="mut c">Tidak ditemukan</p>'}
function viewReels(){const m=$('#main');m.innerHTML=`<div class="seg"><button data-act="go" data-v="explore">Jelajah</button><button class="on">${ic('film')} RVNREELS</button><button data-act="livepage">${ic('live')} Live</button></div><div id="rl">${SK}</div>`;const t=S.tok;
getDocs(query(collection(db,'posts'),where('type','==','reel'),limit(30))).then(async s=>{const ps=s.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>(b.createdAt?.toMillis?.()||0)-(a.createdAt?.toMillis?.()||0));await Promise.all(ps.map(p=>getUser(p.uid)));if(t!==S.tok)return;
$('#rl').className='snap';$('#rl').innerHTML=ps.length?ps.map(p=>{const u=S.users[p.uid];return`<div class="reel">${embed(p.video)}<div class="cap"><div class="row" data-act="go" data-v="profile" data-a="${p.uid}">${av(u)}<b>@${esc(u.username)}</b>${isBlue(u)?BLUE:''}</div><div style="margin-top:6px">${FX.safe(p.text)}</div></div></div>`}).join(''):'<div class="card pad c mut">Belum ada reels. Akun Centang Biru bisa mengunggah dari tombol +</div>'})}
/* ---------- PROFIL ---------- */
