/* ---------- MUSIK OTOMATIS (latar Spotify, 30 detik) ---------- */
const MU={cur:null,loaded:'',io:null,manual:{},title:{},ctl:null,ctlP:null,apiP:null,state:false,pending:null,cut:null,wd:null};
function mkind(u){u=(u||'').trim();const m=u.match(/open\.spotify\.com\/(?:intl-[a-z]+\/)?(track|album|playlist|episode|show)\/(\w+)/);return m?{k:'sp',t:m[1],id:m[2]}:null}
const spUri=k=>`spotify:${k.t}:${k.id}`;
function mline(p){if(!p.music||!mkind(p.music))return'';return`<div class="mline" data-act="mtoggle" data-id="${p.id}" data-url="${esc(p.music)}" data-s="off" role="button" aria-label="Musik latar"><span class="eq"><i></i><i></i><i></i></span><span class="mt">${esc(MU.title[p.music]||'Musik latar')}</span></div>`}
function setLine(pid,st){$$('.mline').forEach(c=>{if(c.dataset.id!==pid)return;c.dataset.s=st;const t=c.querySelector('.mt');if(t)t.textContent=st=='blocked'?'Ketuk layar untuk memutar musik':(MU.title[c.dataset.url]||'Musik latar')})}
function spAPI(){if(window.SpAPI)return Promise.resolve(window.SpAPI);return MU.apiP||(MU.apiP=new Promise((res,rej)=>{window.onSpotifyIframeApiReady=a=>{window.SpAPI=a;res(a)};const s=document.createElement('script');s.src='https://open.spotify.com/embed/iframe-api/v1';s.async=true;s.onerror=()=>{MU.apiP=null;rej(Error('Spotify tidak bisa dimuat'))};document.body.appendChild(s)}))}
function getCtl(uri){if(MU.ctlP)return MU.ctlP;MU.loaded=uri;
MU.ctlP=(async()=>{const API=await spAPI();let box=$('#spbox');if(!box){box=document.createElement('div');box.id='spbox';box.className='mhid';box.setAttribute('aria-hidden','true');box.appendChild(document.createElement('div'));document.body.appendChild(box)}
return await new Promise(res=>API.createController(box.firstChild,{uri,width:300,height:80},c=>{MU.ctl=c;
c.addListener('playback_update',e=>{const pl=!e.data.isPaused,was=MU.state;MU.state=pl;const pid=MU.cur;if(!pid)return;
if(pl&&!was){clearTimeout(MU.wd);MU.pending=null;setLine(pid,'on');clearTimeout(MU.cut);MU.cut=setTimeout(()=>MU.halt(pid),30000)}else if(!pl&&was)setLine(pid,'off')});
c.addListener('ready',()=>{if(MU.cur&&!MU.state&&!MU.manual[MU.cur])try{c.play()}catch{}});
res(c)}))})().catch(e=>{MU.ctlP=null;throw e});return MU.ctlP}
MU.halt=pid=>{if(MU.cur!==pid)return;clearTimeout(MU.cut);try{MU.ctl?.pause()}catch{}setLine(pid,'off')};
MU.play=async(pid,url)=>{const k=mkind(url);if(!k)return;const uri=spUri(k);if(MU.cur===pid&&MU.state)return;
clearTimeout(MU.cut);clearTimeout(MU.wd);if(MU.cur&&MU.cur!==pid)setLine(MU.cur,'off');MU.cur=pid;MU.pending=null;
if(MU.ctl&&MU.loaded===uri&&MU.state){setLine(pid,'on');MU.cut=setTimeout(()=>MU.halt(pid),30000);return}
setLine(pid,'loading');
try{const c=await getCtl(uri);if(MU.cur!==pid)return;if(MU.loaded!==uri){MU.loaded=uri;MU.state=false;c.loadUri(uri)}c.play();
MU.wd=setTimeout(()=>{if(MU.cur===pid&&!MU.state){setLine(pid,'blocked');MU.pending={pid,url}}},5000)}
catch{if(MU.cur===pid){setLine(pid,'blocked');MU.pending={pid,url}}}};
MU.stop=()=>{clearTimeout(MU.cut);clearTimeout(MU.wd);MU.pending=null;try{MU.ctl?.pause()}catch{}MU.state=false;MU.cur=null;
$$('.mline').forEach(c=>{c.dataset.s='off';const t=c.querySelector('.mt');if(t)t.textContent=MU.title[c.dataset.url]||'Musik latar'})};
async function mTitle(url){if(MU.title[url]!==undefined)return;MU.title[url]='';
try{const j=await(await fetch('https://open.spotify.com/oembed?url='+encodeURIComponent(url))).json();MU.title[url]=String(j.title||'').slice(0,60)}catch{}
if(MU.title[url])$$('.mline').forEach(c=>{if(c.dataset.url==url&&c.dataset.s!='blocked'){const t=c.querySelector('.mt');if(t)t.textContent=MU.title[url]}})}
function musicObserve(root){const cs=$$('[data-music]',root).filter(el=>mkind(el.dataset.music));if(!cs.length)return;
if(!MU.io)MU.io=new IntersectionObserver(es=>es.forEach(e=>{const el=e.target,pid=el.dataset.pid;if(!el.isConnected){MU.io.unobserve(el);return}
if(e.isIntersecting){if(!MU.manual[pid])MU.play(pid,el.dataset.music)}else if(MU.cur===pid)MU.stop()}),{rootMargin:'-45% 0px -45% 0px',threshold:0});
cs.forEach(el=>{MU.io.observe(el);mTitle(el.dataset.music)})}
const muUnlock=e=>{const p=MU.pending;if(!p||MU.cur!==p.pid||MU.manual[p.pid]||e.target.closest?.('.mline'))return;MU.pending=null;try{MU.ctl?.play()}catch{}
clearTimeout(MU.wd);MU.wd=setTimeout(()=>{if(MU.cur===p.pid&&!MU.state){setLine(p.pid,'blocked');MU.pending=p}},4000)};
['pointerup','touchend','keydown'].forEach(ev=>document.addEventListener(ev,muUnlock,{passive:true}));
