async function getCat(force){if(S.cat&&!force)return S.cat;let l=[];try{l=(await getDocs(collection(db,'catalog'))).docs.map(d=>{const x=d.data();return{id:d.id,kind:x.kind,n:x.name,p:x.price,i:x.icon||'gift',tier:x.tier||'',active:x.active!==false}})}catch{}
S.catDef=!l.length;S.cat=l.length?l.filter(x=>x.active):CAT_DEF;return S.cat}
