async function sendGift(to,gid,ctx){const it=(await getCat()).find(x=>x.id==gid);if(!it)return;const sr=doc(db,'users',S.uid,'inventory',gid),rr=doc(db,'users',to,'inventory',gid),opid=doc(collection(db,'giftOps')).id;
try{await runTransaction(db,async tx=>{const [s,r]=await Promise.all([tx.get(sr),tx.get(rr)]);const have=s.exists()?s.data().count:0;if(have<1)throw Error('Hadiah habis. Beli lagi di Toko.');
tx.set(doc(db,'giftOps',opid),{from:S.uid,to,gid,qty:1,ctx:ctx||'',createdAt:serverTimestamp()});tx.set(sr,{count:have-1,lastOp:opid});tx.set(rr,{count:(r.exists()?r.data().count:0)+1,lastOp:opid})});
closeSheet();toast(it.n+' terkirim');pushNotif(to,'gift','mengirim '+it.n+' kepadamu')}catch(e){toast(errMsg(e))}}
async function buyCat(id){const it=(await getCat()).find(x=>x.id==id);if(!it)return;if(S.catDef)return toast('Katalog belum siap. Admin perlu membuka dashboard satu kali.');
if(!confirm(`Beli ${it.n} seharga ${nv(it.p)}?`))return;const tid=doc(collection(db,'transfers')).id,ur=doc(db,'users',S.uid),or=doc(db,'users',OFFICIAL_UID),ir=doc(db,'users',S.uid,it.kind=='gift'?'inventory':'assets',id);
try{await runTransaction(db,async tx=>{const [m,o,iv]=await Promise.all([tx.get(ur),tx.get(or),tx.get(ir)]);if(!o.exists())throw Error('Toko belum siap. Hubungi admin.');const mb=m.data().balance||0;if(mb<it.p)throw Error('Saldo noisevn tidak cukup. Top up dulu di RVNBANK.');
tx.set(doc(db,'transfers',tid),{from:S.uid,to:OFFICIAL_UID,amount:it.p,note:'Beli '+it.n,createdAt:serverTimestamp()});
tx.update(ur,{balance:mb-it.p,lastTx:tid,spent:(m.data().spent||0)+it.p});tx.update(or,{balance:(o.data().balance||0)+it.p,lastTx:tid});
tx.set(ir,{count:(iv.exists()?iv.data().count:0)+1,lastOp:tid})});
toast(it.n+' ditambahkan ke inventaris');if(S.view=='shop')viewShop()}catch(e){toast(errMsg(e))}}
