const rb=rank(tb,'balance'),rs=rank(ts,'spent'),owned=(as?as.docs:[]).map(d=>({id:d.id,c:d.data().count||0})).filter(x=>x.c>0).map(x=>({...x,it:cat.find(c=>c.id==x.id)})).filter(x=>x.it);
