function trackSheet(){sheet(`<h3>Unggah lagu</h3><label>Judul</label><input id="tr_t" maxlength="80"><label>Nama artis</label><input id="tr_a" maxlength="60" placeholder="${esc(S.me.displayName||S.me.username)}"><label>Cover (opsional)</label><input id="tr_c" type="file" accept="image/*"><label>File MP3 (maks 600 KB)</label><input id="tr_f" type="file" accept="audio/*"><label>atau link MP3 langsung (untuk lagu penuh)</label><input id="tr_u" placeholder="https://.../lagu.mp3"><div style="height:14px"></div><button class="btn block" data-act="savetrack">Unggah</button><p class="mut">Tanpa server penyimpanan, file yang diunggah langsung dibatasi 600 KB. Untuk lagu penuh pakai link MP3 langsung.</p>`)}
async function saveTrack(btn){const title=$('#tr_t').value.trim(),f=$('#tr_f').files[0],url=$('#tr_u').value.trim(),c=$('#tr_c').files[0];if(!title)return toast('Isi judul lagu');if(!f&&!url)return toast('Pilih file MP3 atau isi link MP3');if(url&&!/^https?:\/\/.+\.(mp3|m4a|ogg|wav)(\?.*)?$/i.test(url))return toast('Link harus berakhiran .mp3, .m4a, .ogg, atau .wav');
if(f&&f.size>600*1024)return toast('File terlalu besar (maks 600 KB). Pakai link MP3 langsung.');btn.disabled=true;
try{const audioData=f?await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f)}):'';const cover=c?await shrink(c,300,.65):'';if((audioData+cover).length>900000)throw Error('Ukuran total terlalu besar');
await setDoc(doc(collection(db,'tracks')),{uid:S.uid,title:title.slice(0,80),artist:(($('#tr_a').value||'').trim()||S.me.displayName||S.me.username||'').slice(0,60),cover,audioUrl:url,audioData,createdAt:serverTimestamp()});closeSheet();toast('Lagu diunggah');viewMusic()}catch(e){toast(errMsg(e));btn.disabled=false}}
function playTrack(id){const x=S.tracks?.[id];if(!x)return;MU.stop();S.tau=S.tau||new Audio();const same=S.tcur==id&&!S.tau.paused;if(same){S.tau.pause();S.tcur=null}else{S.tau.src=x.audioData||x.audioUrl;S.tau.play().catch(()=>toast('Lagu tidak bisa diputar'));S.tcur=id;S.tau.onended=()=>{S.tcur=null;paintTracks()}}paintTracks()}
