newtrack:trackSheet,savetrack:e=>saveTrack(e),tplay:e=>playTrack(e.dataset.id),
async deltrack(e){if(confirm('Hapus lagu ini?')){await deleteDoc(doc(db,'tracks',e.dataset.id)).catch(x=>toast(errMsg(x)));viewMusic()}},
async slike(){const x=S.sv?.list[S.sv.i];if(!x)return;const r=doc(db,'stories',x.id,'likes',S.uid);try{if(S.slk){await deleteDoc(r);S.slk=false}else{await setDoc(r,{at:serverTimestamp()});S.slk=true;pushNotif(x.uid,'story','menyukai ceritamu','slike_'+x.id+'_'+S.uid,{sid:x.id})}$('#sv_lk')?.classList.toggle('on',S.slk)}catch(e){toast(errMsg(e))}},
async ssend(){const x=S.sv?.list[S.sv.i],i=$('#sv_in');if(!x||!i)return;const t=i.value.trim();if(!t)return;if(!FX.guard(t,'story'))return;i.value='';try{await setDoc(doc(collection(db,'stories',x.id,'replies')),{uid:S.uid,text:t.slice(0,300),createdAt:serverTimestamp()});pushNotif(x.uid,'story','mengomentari ceritamu: '+t.slice(0,60),undefined,{sid:x.id});toast('Komentar terkirim')}catch(e){toast(errMsg(e))}},
sgift:e=>{clearTimeout(S.stt);giftSheet(e.dataset.to,'story')},
sviews:()=>storyList('views'),slikes:()=>storyList('likes'),sreplies:()=>storyList('replies'),
amode:e=>authScreen(e.dataset.m),
async login(e){const id=$('#a_id').value.trim(),pw=$('#a_pw').value;if(!id||!pw)return toast('Isi username/Gmail dan sandi');e.disabled=true;
try{let em=id;if(!id.includes('@')){const s=await getDoc(doc(db,'usernames',id.toLowerCase().replace(/^@/,'')));if(!s.exists())throw{code:'auth/user-not-found'};em=s.data().email;if(!em)throw{code:'auth/user-not-found'}}await signInWithEmailAndPassword(auth,em,pw)}catch(x){toast(errMsg(x));e.disabled=false}},
async register(e){const v=i=>$('#'+i).value.trim();e.disabled=true;S.registering=true;
try{const un=v('a_un').toLowerCase();if(!/^[a-z0-9_.]{3,20}$/.test(un))throw Error('Username 3–20 karakter: huruf kecil, angka, _ atau .');if((await getDoc(doc(db,'usernames',un))).exists())throw Error('Username sudah dipakai');
const c=await createUserWithEmailAndPassword(auth,v('a_em'),$('#a_pw').value);try{await createProfile(c.user,{username:un,displayName:v('a_nm'),type:$('#a_ty').value})}catch(x){await c.user.delete().catch(()=>{});throw x}
S.registering=false;await handleUser(auth.currentUser)}catch(x){S.registering=false;toast(errMsg(x));e.disabled=false}},
async forgot(){const id=($('#a_id')?.value||'').trim();if(!id)return toast('Isi username atau Gmail dulu');let em=id;if(!id.includes('@')){const s=await getDoc(doc(db,'usernames',id.toLowerCase().replace(/^@/,'')));if(!s.exists())return toast('Username tidak ditemukan');em=s.data().email}await sendPasswordResetEmail(auth,em);toast('Link reset sandi dikirim ke email kamu')},
async install(){if(S.dip){await askNotif().catch(()=>{});S.dip.prompt();return}const ios=/iPhone|iPad|iPod/i.test(navigator.userAgent);sheet(`<div class="c"><h3>${ic('download')} Pasang RVNOISE</h3><p>${ios?'Ketuk tombol <b>Bagikan</b> di Safari, lalu pilih <b>Tambahkan ke Layar Utama</b>.':'Ketuk menu <b>&#8942;</b> di Chrome, lalu pilih <b>Pasang aplikasi</b> atau <b>Tambahkan ke layar utama</b>.'}</p><p class="mut">Setelah terpasang, aplikasi terbuka layar penuh tanpa bar alamat.</p><button class="btn block" data-act="wclose">Mengerti</button></div>`)},
async google(e){try{await signInWithPopup(auth,new GoogleAuthProvider())}catch(x){toast(errMsg(x))}},
async setup(e){e.disabled=true;try{await createProfile(S.fbUser,{username:$('#s_un').value,displayName:$('#s_nm').value,type:$('#s_ty').value,password:$('#s_pw')?.value});await handleUser(auth.currentUser)}catch(x){toast(errMsg(x));e.disabled=false}},
logout:async()=>{if(S.live)endLive();await signOut(auth)},
