tab:e=>{S.tab=e.dataset.t;viewHome()},
create:()=>createSheet(),ckind:e=>createSheet(e.dataset.k),post:e=>doPost(e.dataset.k,e),
like:toggleLike,cmt:e=>openComments(e.dataset.id),sendcmt:e=>sendComment(e.dataset.id),
