document.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(!el)return;const f=ACT[el.dataset.act]||ADM[el.dataset.act];if(f){e.preventDefault();Promise.resolve(f(el,e)).catch(x=>toast(errMsg(x)))}});

/* ---------- geser untuk pindah menu ---------- */
(()=>{const SW=['home','explore','shop','profile'],skip='.car,.hs,.stories,.seg.scroll,input,textarea,select,video,iframe,.reel,.msgs,.stv,.lroom,.wrow';let x0=0,y0=0,t0=0,ok=false;
document.addEventListener('touchstart',e=>{const t=e.touches[0];x0=t.clientX;y0=t.clientY;t0=Date.now();ok=e.touches.length==1&&!!S.me&&!S.adm&&SW.includes(S.view)&&(S.view!='profile'||!S.arg||S.arg==S.uid)&&!e.target.closest(skip)&&!document.querySelector('#sheet,#stv')},{passive:true});
document.addEventListener('touchend',e=>{if(!ok)return;ok=false;const t=e.changedTouches[0],dx=t.clientX-x0,dy=t.clientY-y0;if(Math.abs(dx)>80&&Math.abs(dy)<60&&Math.abs(dx)>Math.abs(dy)*1.8&&Date.now()-t0<600){const n=SW.indexOf(S.view)+(dx<0?1:-1);if(n>=0&&n<SW.length){S.dir=dx<0?'l':'r';go(SW[n],n==3?S.uid:undefined)}}},{passive:true})})();
